   208→        private void SetNewBalance(Address address, in UInt256 balanceChange, IReleaseSpec releaseSpec, bool isSubtracting)
   209→        {
   210→            _needsStateRootUpdate = true;
   211→
   212→            Account GetThroughCacheCheckExists()
   213→            {
   214→                Account result = GetThroughCache(address);
   215→                if (result is null)
   216→                {
   217→                    ThrowNonExistingAccount();
   218→                }
   219→
   220→                return result;
   221→
   222→                [DoesNotReturn, StackTraceHidden]
   223→                static void ThrowNonExistingAccount()
   224→                    => throw new InvalidOperationException("Updating balance of a non-existing account");
   225→            }
   226→
   227→            bool isZero = balanceChange.IsZero;
   228→            if (isZero)
   229→            {
   230→                // this also works like this in Geth (they don't follow the spec ¯\_(*~*)_/¯)
   231→                // however we don't do it because of a consensus issue with Geth, just to avoid
   232→                // hitting non-existing account when subtracting Zero-value from the sender
   233→                if (releaseSpec.IsEip158Enabled && !isSubtracting)
   234→                {
   235→                    Account touched = GetThroughCacheCheckExists();
   236→
   237→                    if (_logger.IsTrace) TraceTouch(address);
   238→                    if (touched.IsEmpty)
   239→                    {
   240→                        PushTouch(address, touched, releaseSpec, true);
   241→                    }
   242→                }
   243→
   244→                return;
   245→            }
   246→
   247→            Account account = GetThroughCacheCheckExists();
   248→
   249→            if (isSubtracting && account.Balance < balanceChange)
   250→            {
   251→                ThrowInsufficientBalanceException(address);
   252→            }
   253→
   254→            UInt256 newBalance = isSubtracting ? account.Balance - balanceChange : account.Balance + balanceChange;
   255→
   256→            Account changedAccount = account.WithChangedBalance(newBalance);
   257→            if (_logger.IsTrace) TraceUpdate(address, in balanceChange, isSubtracting, account, in newBalance);
   258→
   259→            PushUpdate(address, changedAccount);
   260→
   261→            [MethodImpl(MethodImplOptions.NoInlining)]
   262→            void TraceTouch(Address address) => _logger.Trace($"Touch {address} (balance)");
   263→
   264→            [MethodImpl(MethodImplOptions.NoInlining)]
   265→            void TraceUpdate(Address address, in UInt256 balanceChange, bool isSubtracting, Account account, in UInt256 newBalance)
   266→                => _logger.Trace($"Update {address} B {account.Balance.ToHexString(skipLeadingZeros: true)} -> {newBalance.ToHexString(skipLeadingZeros: true)} ({(isSubtracting ? "-" : "+")}{balanceChange})");
   267→
   268→            [DoesNotReturn, StackTraceHidden]
   269→            static void ThrowInsufficientBalanceException(Address address)
   270→                => throw new InsufficientBalanceException(address);
   271→        }
